bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
docker inspect -f 'bot running={{.State.Running}} restarting={{.State.Restarting}} restart_count={{.RestartCount}} started={{.State.StartedAt}}' deploy-gaybbs-1
docker inspect -f 'db running={{.State.Running}}' deploy-postgres-1
systemctl --user is-active gace-userbot-verify.service
docker exec deploy-gaybbs-1 sha256sum /app/gaybbs.mjs
docker logs --since 120m --tail 4000 deploy-gaybbs-1 2>&1 | python3 -c 'import sys,re,collections
s=sys.stdin.read()
for k,v in sorted(collections.Counter(re.findall(r"reason:\s*[\x27\x22]([A-Z][A-Z0-9_]{3,100})[\x27\x22]",s)).items()):print("ERROR_CODE",k,v)
for k,v in sorted(collections.Counter(re.findall(r"\[GAYBBS_ERROR\]\s+(\w+)\s+(\w+)",s)).items()):print("BOT_ERROR",*k,v)
for k in ["GAYBBS_BOT_READY","POST_PUBLICATION_FAILED","FEATURE_RELEASE_NOT_VERIFIED","NOTICE_SOURCE_NOT_OWNED","PUBLISH_NEEDS_RECONCILE","NOTICE_EDITOR_ERROR_EDIT_FAILED","409:","401:","429:","Bad Request","ETELEGRAM","ETIMEDOUT","FATAL","ECONNREFUSED"]:print("LOG_COUNT",k,s.count(k))'
docker exec deploy-postgres-1 psql -X -v ON_ERROR_STOP=1 -U gace -d gaybbs -Atqc "
SELECT 'notice_release',enabled,length(source_commit)=40,length(trim(ci_evidence))>0,length(trim(gserver_runtime_evidence))>0,length(trim(telegram_e2e_evidence))>0,approved_by IS NOT NULL FROM gaybbs_feature_release_gates WHERE feature='announcement';
SELECT 'notice_drafts',step,count(*) FROM public_post_drafts WHERE module='announcement' AND data->>'kind' IN ('announcement','preview') GROUP BY step;
SELECT 'notice_sources',status,count(*) FROM announcement_posts WHERE kind IN ('announcement','preview') GROUP BY status;
SELECT 'notice_delivery',d.status,count(*) FROM posting_deliveries d JOIN announcement_posts p ON p.announcement_id::text=d.source_id WHERE d.source_type='announcement' AND p.kind IN ('announcement','preview') GROUP BY d.status;
"
